const k=({entryPrice:l,exitPrice:a,stopLoss:c,positionSize:p,direction:i,fee:u})=>{const t=parseFloat(l)||0,o=parseFloat(a)||0,r=parseFloat(c)||0,n=parseInt(p)||0,P=parseFloat(u)||0;if(t===0||n===0)return{pnl:0,pnlPercent:0,rMultiple:0};const s=(i==="long"?(o-t)*n:(t-o)*n)-P,F=t>0?s/(t*n)*100:0,e=(r>0?Math.abs(t-r):0)*n,M=e>0?s/e:0;return{pnl:s,pnlPercent:F,rMultiple:e>0?M.toFixed(2):null}};export{k as c};
